          label: "Email address",
          type: "email",
          autocomplete: "email",
          placeholder: "alex@example.com",
          required: true,
          validate(value) {
            if (!value.trim()) return "Email address is required.";
            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
              ? ""
              : "Enter a valid email address, such as alex@example.com.";
          },
        },
        {
          id: "phone",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          placeholder: "+1 555 123 4567",
          required: false,
          helperText: "Optional. Use 7 to 15 digits and include country code if outside your region.",
          validate(value) {
            if (!value.trim()) return "";
            return /^\+?[0-9\s().-]{7,20}$/.test(value)
              ? ""
              : "Enter a phone number using digits, spaces, parentheses, hyphens, or an optional plus sign.";
          },
        },
      ];

      const state = {
        values: Object.fromEntries(fields.map((field) => [field.id, ""])),
        errors: Object.fromEntries(fields.map((field) => [field.id, ""])),
        submitted: false,
      };

      function FormField({ field, value, error }) {
        const describedBy = [
          field.helperText ? `${field.id}-helper` : "",
          error ? `${field.id}-error` : "",
        ]
          .filter(Boolean)
          .join(" ");

        return `
          <div class="form-field">
            <label for="${field.id}">
              ${field.label}${field.required ? ' <span class="required" aria-hidden="true">*</span>' : ""}
            </label>
            <input
              id="${field.id}"
              name="${field.id}"
              type="${field.type}"
              autocomplete="${field.autocomplete}"
              placeholder="${field.placeholder}"
