                : ""
            }
            <p class="error-message" id="${field.id}-error" aria-live="polite">${error}</p>
          </div>
        `;
      }

      function ContactForm() {
        return `
          <section class="support-card" aria-labelledby="support-title">
            <p class="eyebrow">Support request</p>
            <h1 id="support-title">How can we help?</h1>
            <p class="intro">
              Share your contact details and our support team will follow up as soon as possible.
