        --panel-border: #27324d;
        --text: #f5f7fb;
        --muted: #aab6d3;
        --accent: #6ee7f9;
        --accent-strong: #22d3ee;
        --danger: #fda4af;
        --danger-bg: rgba(244, 63, 94, 0.12);
