        padding: 2rem;
        background:
          radial-gradient(circle at top left, rgba(34, 211, 238, 0.18), transparent 30rem),
          linear-gradient(135deg, #070b16 0%, var(--bg) 48%, #111827 100%);
        color: var(--text);
