        color: #7583a5;
      }

      input:focus {
        border-color: var(--accent-strong);
        outline: none;
        box-shadow: 0 0 0 0.25rem rgba(34, 211, 238, 0.18);
      }

      input[aria-invalid="true"] {
        border-color: var(--danger);
        background: var(--danger-bg);
      }

      .helper-text,
      .error-message,
      .success-message {
        margin: 0.45rem 0 0;
        font-size: 0.92rem;
        line-height: 1.45;
      }

      .helper-text {
        color: var(--muted);
      }

      .error-message {
        color: var(--danger);
      }

      .success-message {
        color: var(--success);
      }

      button {
        width: 100%;
        min-height: 3.25rem;
        margin-top: 0.5rem;
        border: 0;
        border-radius: 999px;
        background: linear-gradient(135deg, var(--accent-strong), #818cf8);
        color: #06111f;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        letter-spacing: 0.01em;
        transition:
          filter 160ms ease,
          transform 160ms ease,
          box-shadow 160ms ease;
      }

      button:hover {
        filter: brightness(1.07);
        transform: translateY(-1px);
        box-shadow: 0 1rem 2rem rgba(34, 211, 238, 0.18);
      }

      button:focus-visible {
        outline: 0.25rem solid rgba(245, 247, 251, 0.72);
        outline-offset: 0.2rem;
      }
    </style>
  </head>
  <body>
    <main id="app"></main>

    <script>
      const fields = [
        {
          id: "fullName",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          placeholder: "Alex Morgan",
          required: true,
          validate(value) {
            return value.trim() ? "" : "Full name is required.";
          },
        },
        {
          id: "email",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          placeholder: "alex@example.com",
          required: true,
          validate(value) {
            if (!value.trim()) return "Email address is required.";
            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
              ? ""
              : "Enter a valid email address, such as alex@example.com.";
          },
        },
        {
          id: "phone",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          placeholder: "+1 555 123 4567",
          required: false,
          helperText: "Optional. Use 7 to 15 digits and include country code if outside your region.",
          validate(value) {
            if (!value.trim()) return "";
            return /^\+?[0-9\s().-]{7,20}$/.test(value)
              ? ""
              : "Enter a phone number using digits, spaces, parentheses, hyphens, or an optional plus sign.";
          },
        },
      ];

      const state = {
        values: Object.fromEntries(fields.map((field) => [field.id, ""])),
        errors: Object.fromEntries(fields.map((field) => [field.id, ""])),
        submitted: false,
      };

      function FormField({ field, value, error }) {
        const describedBy = [
          field.helperText ? `${field.id}-helper` : "",
          error ? `${field.id}-error` : "",
        ]
          .filter(Boolean)
          .join(" ");

        return `
          <div class="form-field">
            <label for="${field.id}">
              ${field.label}${field.required ? ' <span class="required" aria-hidden="true">*</span>' : ""}
            </label>
            <input
              id="${field.id}"
              name="${field.id}"
              type="${field.type}"
              autocomplete="${field.autocomplete}"
              placeholder="${field.placeholder}"
              value="${value.replace(/"/g, "&quot;")}"
              ${field.required ? "required" : ""}
              aria-invalid="${error ? "true" : "false"}"
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
            />
            ${
              field.helperText
                ? `<p class="helper-text" id="${field.id}-helper">${field.helperText}</p>`
                : ""
            }
            <p class="error-message" id="${field.id}-error" aria-live="polite">${error}</p>
          </div>
        `;
      }

      function ContactForm() {
        return `
          <section class="support-card" aria-labelledby="support-title">
            <p class="eyebrow">Support request</p>
            <h1 id="support-title">How can we help?</h1>
            <p class="intro">
              Share your contact details and our support team will follow up as soon as possible.
              Fields marked with an asterisk are required.
            </p>
            <form id="support-form" novalidate>
              ${fields
                .map((field) =>
                  FormField({
                    field,
                    value: state.values[field.id],
                    error: state.errors[field.id],
                  }),
                )
                .join("")}
              <button type="submit">Contact support</button>
              <p class="success-message" id="form-status" role="status">
                ${state.submitted ? "Thanks. Your support request is ready to send." : ""}
              </p>
            </form>
          </section>
        `;
      }

      function validateField(field) {
        state.errors[field.id] = field.validate(state.values[field.id]);
      }

      function render() {
        document.getElementById("app").innerHTML = ContactForm();

        fields.forEach((field) => {
          const input = document.getElementById(field.id);
          input.addEventListener("input", (event) => {
            state.values[field.id] = event.target.value;
            validateField(field);
            state.submitted = false;
            render();
            document.getElementById(field.id).focus();
          });
        });

        document.getElementById("support-form").addEventListener("submit", (event) => {
          event.preventDefault();
          fields.forEach(validateField);
          state.submitted = fields.every((field) => !state.errors[field.id]);
          render();

          if (!state.submitted) {
            const firstInvalidField = fields.find((field) => state.errors[field.id]);
            document.getElementById(firstInvalidField.id).focus();
          }
        });
      }

      render();
    </script>
  </body>
</html>
