    <script>
      function FormFieldComponent({ input, error, validate }) {
        function setError(message) {
          error.textContent = message;
          input.setAttribute("aria-invalid", message ? "true" : "false");
        }

        return {
          input,
          validate() {
            const message = validate(input.value);
            setError(message);
            return !message;
          },
          clearStatus() {
            document.getElementById("form-status").textContent = "";
          },
        };
      }

      function ContactFormComponent(form) {
        const fields = [
          FormFieldComponent({
            input: document.getElementById("fullName"),
            error: document.getElementById("fullName-error"),
            validate(value) {
              return value.trim() ? "" : "Full name is required.";
            },
          }),
          FormFieldComponent({
            input: document.getElementById("email"),
            error: document.getElementById("email-error"),
            validate(value) {
              if (!value.trim()) return "Email address is required.";
              return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
                ? ""
                : "Enter a valid email address, such as alex@example.com.";
            },
          }),
          FormFieldComponent({
            input: document.getElementById("phone"),
            error: document.getElementById("phone-error"),
            validate(value) {
              if (!value.trim()) return "";

              const digits = value.replace(/\D/g, "");
              const usesAllowedCharacters = /^\+?[0-9\s().-]+$/.test(value);
              return usesAllowedCharacters && digits.length >= 7 && digits.length <= 15
                ? ""
                : "Enter a phone number with 7 to 15 digits using only spaces, parentheses, hyphens, periods, or an optional plus sign.";
            },
          }),
        ];

        fields.forEach((field) => {
          field.input.addEventListener("input", () => {
            field.clearStatus();
            field.validate();
          });
          field.input.addEventListener("blur", field.validate);
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();

          const isValid = fields.map((field) => field.validate()).every(Boolean);
          const status = document.getElementById("form-status");

          if (isValid) {
            status.textContent = "Thanks. Your support request is ready to send.";
            form.reset();
            fields.forEach((field) => field.validate());
            return;
          }

          status.textContent = "";
          fields.find((field) => field.input.getAttribute("aria-invalid") === "true").input.focus();
        });
      }

      ContactFormComponent(document.getElementById("support-form"));
    </script>
